/* Consumer journey screens share the existing view registry. */
let journeyData=null,journeyAccount=null,journeyLoading=false;
async function loadJourney(){if(!account||journeyLoading)return;journeyLoading=true;const uid=account.id;try{const data=await api('journey');if(account?.id===uid){journeyData=data;journeyAccount=uid;render()}}catch(e){toast(e.message)}finally{journeyLoading=false}}
async function journeyAction(action,b){await api('journey-'+action,b);await loadJourney();await refreshCloud()}
function journeyForm(title,fields,action,extra={}){formAsync(title,fields+'<button class="btn">Сохранить</button>',async f=>journeyAction(action,{...extra,...Object.fromEntries(f)}))}
function journeyPage(){
 if(!account)return '<section class="panel"><h2>🧺 Ваша корзина начинается здесь</h2><button class="btn" onclick="profile()">Войти в хозяйство</button></section>';
 if(!journeyData||journeyAccount!==account.id)return '<p role="status">🌱 Собираем новости вашего хозяйства…</p>';
 const d=journeyData,ready=(batchData||[]).filter(b=>b.verified&&b.balance_grams>b.reserved_grams&&Date.parse(b.expires_at)>Date.now());
 return `<section class="basket-hero"><span>🧺</span><div><h1>Моя корзина</h1><p>Вы выбираете овощи. Мы показываем путь от посадки до вашего стола.</p><button class="btn" onclick="chooseFoodPlan()">🥗 Что хочу вырастить</button> <button class="btn light" onclick="gardenJourney()">Как это устроено</button></div></section><div class="journey-stats"><a href="#home">🌱 Растёт на грядках <b>${myPlots().filter(p=>['planted','growing','harvest_ready'].includes(p.growing_state)).length}</b></a><a href="#warehouse">🧺 Готовых партий <b>${ready.length}</b></a><a href="#lifecycle">🚚 В пути <b>${(lifeData?.deliveries||[]).filter(x=>x.status==='shipped').length}</b></a></div><section class="panel"><h2>Что можно забрать</h2>${ready.map(b=>`<div class="event"><b>${esc(b.crop)}</b> · ${(b.balance_grams-b.reserved_grams)/1000} кг <small>До ${fmt(b.expires_at)}</small><button class="btn light" onclick="showPassport('${b.id}')">Путь продукта</button></div>`).join('')||'<p>Здесь появится урожай после сбора и приёмки.</p>'}<button class="btn" onclick="basketForm()">🚚 Собрать корзину домой</button></section><section class="panel"><h2>👩‍🌾 План заботы</h2><p>До 8 согласованных работ, суммарно до 100 минут за 30 дней на хозяйство входят в демоподписку. Материалы и монтаж согласуются отдельно. Оплата подписки сама по себе не подтверждает физическое выполнение.</p>${d.schedules.map(s=>`<div class="event"><b>№${s.plot_id} · ${esc(opsData?.services.find(x=>x.code===s.service_code)?.title||s.service_code)}</b><p>${fmt(s.due_at)} · ${esc(s.reason)}</p><small>${({planned:'Запланировано',requested:'Передано в работы',cancelled:'Отменено'})[s.status]}</small>${account.role==='admin'&&s.status==='planned'?`<button class="btn" onclick="releaseCare('${s.id}')">Передать в работы без доплаты</button>`:''}</div>`).join('')||'<p>Садовник ещё не составил расписание. Можно отправить пожелания к уходу.</p>'}<button class="btn light" onclick="location.hash='lifecycle'">Управлять подписками</button>${account.role==='admin'?'<button class="btn" onclick="scheduleCare()">Добавить работу в план</button>':''}</section><section class="panel"><h2>📦 Места хранения</h2>${d.locations.map(l=>`<p>${l.kind==='fridge'?'❄️':'📦'} ${esc(l.name)} · ${l.capacity_grams===null?'без лимита вместимости':Number(l.capacity_grams)/1000+' кг'}<br><small>${esc(l.conditions)}</small></p>`).join('')}<p>Срок каждой партии подтверждает управляющий. При завершении подписки урожай не исчезает: согласуйте продление или доставку.</p>${account.role==='admin'?'<button class="btn light" onclick="storageSetup()">Настроить хранение</button>':''}</section><section class="panel"><h2>🌟 Ваши события</h2>${d.achievements.map(a=>`<p>${a.code==='first_basket'?'🧺 Первая полученная корзина':'🌱 Первый принятый урожай'} · ${fmt(a.achieved_at)}</p>`).join('')||'<p>Первый урожай и первая полученная корзина станут памятными событиями. За лишний полив и покупки наград нет.</p>'}</section><section class="panel"><h2>💬 Решаем вопросы</h2><button class="btn light" onclick="incidentForm()">Сообщить о проблеме</button>${d.incidents.map(i=>`<div class="event"><p>${esc(i.description)}</p><strong>${i.status==='resolved'?'Решено':'Ожидает решения'}</strong><p>${esc(i.resolution||'')}</p>${i.refund_kopecks?`<p>Возвращено: ${money(i.refund_kopecks)} демосредствами</p>`:''}${account.role==='admin'&&i.status!=='resolved'?`<button class="btn" onclick="resolveIncident('${i.id}')">Принять решение</button>`:''}</div>`).join('')}</section>${account.role==='admin'?'<section class="panel"><h2>🔎 Подтверждения фермы</h2><button class="btn light" onclick="evidenceForm()">Добавить фото или измерение</button><button class="btn light" onclick="dimensionsForm()">Подтвердить размеры грядки</button></section>':''}`;
}
function scheduleCare(){formAsync('👩‍🌾 Работа в плане заботы',sp()+`<label>Работа<select name="service">${['inspect','water','feed','weed'].map(code=>`<option value="${code}">${esc(opsData?.services.find(x=>x.code===code)?.title||code)}</option>`).join('')}</select></label><label>Посадка<select name="cycle"><option value="">Если одна — определить автоматически</option>${(seasonData?.cycles||[]).filter(c=>c.approved&&!c.ended_on).map(c=>`<option value="${c.id}">№${c.plot_id} · ${esc(c.crop)}</option>`).join('')}</select></label><label>Плановая дата<input type="datetime-local" name="due" required></label><label>Основание: состояние почвы, растения, условия<textarea name="reason" minlength="20" required></textarea></label><button class="btn">Сохранить план</button>`,async f=>journeyAction('schedule',{...Object.fromEntries(f),plot:Number(f.get('plot')),due:new Date(f.get('due')).toISOString()}))}
async function releaseCare(id){try{await journeyAction('schedule-order',{id});toast('Работа создана без доплаты. Назначьте исполнителя и время.')}catch(e){toast(e.message)}}
function storageSetup(){formAsync('📦 Хранение',`<label>Название<input name="name" required></label><label>Город<select name="city"><option value="krasnodar">Белореченск</option><option value="moscow">Москва</option><option value="petersburg">Санкт-Петербург</option></select></label><label>Тип<select name="kind"><option value="pantry">Кладовая</option><option value="fridge">Холодильник</option></select></label><label>Вместимость в кг · пусто = без лимита<input type="number" name="capacity" min="1"></label><label>Подтверждённые условия<textarea name="conditions" minlength="10" required></textarea></label><button class="btn">Добавить место</button>`,async f=>journeyAction('storage',{...Object.fromEntries(f),capacity:f.get('capacity')?Math.round(Number(f.get('capacity'))*1000):null}))}
function dimensionsForm(){formAsync('📏 Фактические размеры',sp()+'<label>Ширина, м<input name="width" type="number" min="0.1" step="0.01" required></label><label>Длина, м<input name="length" type="number" min="0.1" step="0.01" required></label><button class="btn">Подтвердить измерения</button>',async f=>journeyAction('dimensions',{plot:Number(f.get('plot')),width:Number(f.get('width')),length:Number(f.get('length'))}))}
function evidenceForm(){journeyForm('📸 Подтверждение фермы','<label>Объект<select name="entity"><option value="batch">Партия</option><option value="plot">Грядка</option><option value="equipment">Оборудование</option></select></label><label>Номер объекта<input name="id" required></label><label>Подтверждение<select name="kind"><option value="photo">Фото</option><option value="measurement">Измерение</option><option value="inspection">Осмотр</option></select></label><label>HTTPS-ссылка на фото<input name="url" type="url"></label><label>Описание<textarea name="description" minlength="10" required></textarea></label>','evidence')}
function incidentForm(entity,id){const options=[...(opsData?.orders||[]).map(o=>({entity:'order',id:o.id,label:o.title})),...(lifeData?.deliveries||[]).map(d=>({entity:'delivery',id:d.id,label:'Корзина · '+d.recipient}))];formAsync('💬 Расскажите о проблеме',`<label>Заказ<select name="target">${options.map(o=>`<option value="${o.entity}:${o.id}" ${o.id===id?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label><label>Что произошло<textarea name="description" minlength="10" required></textarea></label><button class="btn">Отправить на проверку</button>`,async f=>{const [entity,id]=f.get('target').split(':');await journeyAction('incident',{entity,id,description:f.get('description')})})}
function resolveIncident(id){formAsync('Решение по обращению','<label>Результат проверки<textarea name="resolution" minlength="10" required></textarea></label><label>Возврат за работу или доставку, демо-₽<input type="number" name="refund" min="0" step="0.01" value="0"></label><label><input type="checkbox" name="stop"> Остановить начатую работу после проверки</label><p>Возврат ограничен фактически оплаченной суммой. Возвращается только оплата выбранной услуги; стоимость самих продуктов рассматривается отдельно.</p><button class="btn">Подтвердить решение</button>',async f=>journeyAction('resolve',{id,resolution:f.get('resolution'),refund:Math.round(Number(f.get('refund'))*100),stop:f.get('stop')==='on'}))}
function marketStage(id,stage){formAsync('🧺 Изменение заказа','<label>Причина или результат<textarea name="report" minlength="10" required></textarea></label><button class="btn">Подтвердить</button>',async f=>{await api('market-transition',{id,stage,report:f.get('report')});await loadJourney();walletData=null;toast(stage==='received'?'Полученные материалы добавлены в запасы':'Заказ обновлён')})}
changeDelivery=async function(id,status){if(['confirmed','shipped'].includes(status)){formAsync(status==='confirmed'?'🚚 Согласование прибытия':'📦 Проверка отправки',status==='confirmed'?'<label>Ожидаемое прибытие<input name="expected" type="datetime-local" required></label><p>Все продукты должны сохранять срок до прибытия.</p><button class="btn">Подтвердить</button>':'<label>Фактическая комплектация, упаковка и условия перевозки<textarea name="packing" minlength="20" required></textarea></label><button class="btn">Подтвердить отправку</button>',async f=>lifeAction('delivery-update',{id,status,...Object.fromEntries(f),...(f.get('expected')?{expected:new Date(f.get('expected')).toISOString()}:{})}));return}try{await lifeAction('delivery-update',{id,status})}catch(e){toast(e.message)}};
const changeOrderCore=changeOrder;changeOrder=async function(id,to){const order=opsData?.orders.find(x=>x.id===id);if(to==='done'&&order?.service_code==='inspect'){formAsync('🔎 Результат осмотра','<label>Состояние<select name="state">'+Object.entries(growingLabels).filter(([k])=>k!=='unchecked').map(([k,v])=>`<option value="${k}">${v}</option>`).join('')+'</select></label><p>Демоосмотр меняет только игровое состояние участка. Физическое состояние хранится отдельно.</p><button class="btn">Принять осмотр</button>',async f=>{await api('order-update',{id,to,state:f.get('state')});await refreshCloud()});return}return changeOrderCore(id,to)};
reportDeliveryIssue=id=>incidentForm('delivery',id);
farmViews.add(()=>{
 if(account&&['#basket','#settings'].includes(location.hash)&&journeyAccount!==account.id&&!journeyLoading)queueMicrotask(loadJourney);

 if(account&&['#settings','#warehouse','#lifecycle','#season'].includes(location.hash))document.getElementById('app').insertAdjacentHTML('afterbegin','<a class="basket-link" href="#basket">🧺 Моя корзина · уход · помощь</a>');
 document.querySelector('.garden-guide')?.setAttribute('onclick',"location.hash='basket'");
 if(location.hash==='#settings')document.getElementById('app').insertAdjacentHTML('beforeend','<section class="panel"><h2>📱 Приложение на телефоне</h2><p>iPhone: в Safari откройте «Поделиться» → «На экран Домой». Android: в меню браузера выберите «Установить приложение» или «Добавить на главный экран».</p><p>Обновления загружаются при открытии. Закрытый доступ Netlify сохраняется. Без связи нельзя оформлять заказы.</p><button class="btn light" onclick="checkFarmUpdate()">Проверить обновление</button></section>');
});
addEventListener('hashchange',()=>{if(['#basket','#settings'].includes(location.hash)){loadJourney();if(account)loadLife();}});
async function checkFarmUpdate(){if(modal.open){toast('Сначала сохраните или закройте форму');return}try{const r=await fetch('/version.json',{cache:'no-store'});const v=await r.json();toast('Версия '+v.version+'. Обновите страницу после завершения действий.')}catch{toast('Нет связи. Ваши серверные данные сохранены.')}}
addEventListener('offline',()=>toast('Нет связи. Заказы можно оформить после подключения.'));
if(account)loadJourney();render();
async function supplyOfferForm(){await loadJourney();if(!journeyData){loadJourney();toast('Откройте ещё раз после загрузки запасов');return}const supplies=journeyData.supplies.filter(s=>Number(s.balance)>Number(s.reserved));if(!supplies.length){toast('Сначала получите семена или материалы на склад');return}formAsync('🌱 Продать из запасов',`<label>Материал<select name="id">${supplies.map(s=>`<option value="${s.id}">${esc(s.name)} · свободно ${Number(s.balance)-Number(s.reserved)} ${esc(s.unit)}</option>`).join('')}</select></label><label>Количество<input name="quantity" type="number" min="0.001" step="0.001" required></label><label>Цена за всё, демо-₽<input name="price" type="number" min="1" step="0.01" required></label><p>Предложение увидят другие пользователи. Указанное количество зарезервируется.</p><button class="btn">Разместить предложение</button>`,async f=>journeyAction('supply-offer',{id:f.get('id'),quantity:Number(f.get('quantity')),price:Math.round(Number(f.get('price'))*100)}))}
demoSell=supplyOfferForm;
function buySupply(id){const o=journeyData?.offers.find(x=>x.id===id);if(!o)return;const key=crypto.randomUUID();formAsync('🌱 Покупка материала',`<h3>${esc(o.name)}</h3><p>${Number(o.quantity)} ${esc(o.unit)} · ${money(o.price_kopecks)} демосредствами</p><p>Материал перейдёт в ваши запасы. Физическую передачу согласует ферма.</p><button class="btn">Купить демосредствами</button>`,async()=>{await journeyAction('supply-buy',{id,key});walletData=null})}
async function cancelSupply(id){try{await journeyAction('supply-cancel',{id})}catch(e){toast(e.message)}}
function rentalReturn(id){journeyForm('📦 Возврат оборудования','<label>Результат осмотра при возврате<textarea name="report" minlength="10" required></textarea></label>','rental-return',{id})}
function equipmentUpdate(id){journeyForm('🪵 Обслуживание оборудования','<label>Состояние<select name="condition"><option value="installed">Установлено</option><option value="maintenance">Нужно обслуживание</option><option value="retired">Снято с эксплуатации</option></select></label><label>Следующая проверка<input name="due" type="datetime-local"></label><label>После окончания аренды<textarea name="disposition" minlength="10" required></textarea></label><label>Результат осмотра<textarea name="report" minlength="10" required></textarea></label>','equipment',{id})}
function receiveBasket(id){const d=lifeData?.deliveries.find(x=>x.id===id);if(!d)return;formAsync('🧺 Что приехало в корзине?',`${(d.items||[]).map(i=>`<label>${esc(i.crop)} · отправлено ${i.grams/1000} кг<input name="grams_${i.batch}" type="number" min="0" max="${i.grams/1000}" value="${i.grams/1000}" step="0.001" required></label><label>Замечание, если есть<input name="issue_${i.batch}" maxlength="500"></label>`).join('')}<p>При недостаче или повреждении автоматически создадим обращение управляющему.</p><button class="btn">Подтвердить получение</button>`,async f=>{await journeyAction('receipt',{id,items:d.items.map(i=>({id:i.batch,grams:Math.round(Number(f.get('grams_'+i.batch))*1000),issue:f.get('issue_'+i.batch)}))});await loadLife()})}
const deliveryWithChecks=changeDelivery;changeDelivery=async function(id,status){if(status==='delivered')return receiveBasket(id);return deliveryWithChecks(id,status)};
farmViews.add(()=>{
 if(account&&['#market','#season'].includes(location.hash)&&journeyAccount!==account.id&&!journeyLoading)queueMicrotask(loadJourney);
 if(location.hash==='#market'&&journeyData&&journeyAccount===account?.id)document.getElementById('app').insertAdjacentHTML('beforeend',`<section class="panel"><h2>🌱 Материалы соседей</h2>${journeyData.offers.map(o=>`<div class="event"><h3>${esc(o.name)}</h3><p>${Number(o.quantity)} ${esc(o.unit)} · ${money(o.price_kopecks)} за всё</p>${o.owner_id===account.id?`<button class="btn light" onclick="cancelSupply('${o.id}')">Снять предложение</button>`:`<button class="btn" onclick="buySupply('${o.id}')">Купить демосредствами</button>`}</div>`).join('')||'<p>Здесь появятся предложения из запасов пользователей.</p>'}</section>`);
 if(location.hash==='#basket'&&journeyData&&journeyAccount===account?.id)document.getElementById('app').insertAdjacentHTML('beforeend',`<section class="panel"><h2>🛠️ Оборудование и аренда</h2>${journeyData.marketRentals.map(r=>`<div class="event"><b>${esc(demoCatalog.find(x=>x.id===r.catalog_id)?.name||r.catalog_id)}</b><p>${r.quantity} шт. · ${fmt(r.starts_at)} — ${fmt(r.ends_at)} · ${r.status==='active'?'В аренде':'Возвращено'}</p><p>${esc(r.condition_report)}</p>${account.role==='admin'&&r.status==='active'?`<button class="btn light" onclick="rentalReturn('${r.id}')">Принять возврат</button>`:''}</div>`).join('')||'<p>Арендованного оборудования пока нет.</p>'}${(lifeData?.equipment||[]).map(e=>`<div class="event"><b>Грядка №${e.plot_id} · ${esc(e.catalog_id)}</b><p>${e.is_simulation?'Демонстрационная установка':'Установка подтверждена'} · ${esc(e.condition)}</p><p>${esc(e.end_of_lease)}</p>${account.role==='admin'?`<button class="btn light" onclick="equipmentUpdate('${e.id}')">Обслуживание</button>`:''}</div>`).join('')}</section>`);
});
let farmServiceWorker=null;
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).then(r=>{farmServiceWorker=r;r.addEventListener('updatefound',()=>{const worker=r.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)toast('Доступна новая версия. Обновите её в профиле после сохранения форм.')})})}).catch(()=>{});
const inspectFarmVersion=checkFarmUpdate;
checkFarmUpdate=async function(){if(modal.open){toast('Сначала сохраните или закройте форму');return}if(farmServiceWorker){await farmServiceWorker.update();if(farmServiceWorker.waiting){farmServiceWorker.waiting.postMessage('ACTIVATE_UPDATE');toast('Обновление подготовлено. Перезапустите приложение после завершения действий.');return}}return inspectFarmVersion()};
newBatch=async function(){if(!account)return profile();await loadSeason();const cycles=(seasonData?.cycles||[]).filter(c=>c.owner_id===account.id&&c.approved&&!c.ended_on);if(!cycles.length){toast('Сначала согласуйте посадку с управляющим');return}const key=crypto.randomUUID();formAsync('🧺 Записать фактический сбор',`<label>Посадка<select name="cycle">${cycles.map(c=>`<option value="${c.id}">№${c.plot_id} · ${esc(c.crop)}</option>`).join('')}</select></label><label>Дата сбора<input type="date" name="date" required></label><label>Масса, кг<input name="kg" type="number" min="0.001" max="100000" step="0.001" required></label><p>Масса после взвешивания. Запись требует приёмки сотрудником.</p><button class="btn">Записать сбор</button>`,async f=>{const cycle=cycles.find(c=>c.id===f.get('cycle'));await api('batch-create',{key,cycle:cycle.id,plot:cycle.plot_id,crop:cycle.crop,date:f.get('date'),grams:Math.round(Number(f.get('kg'))*1000)});await loadBatches()})};
const roomOrderLoaded=roomOrder;roomOrder=async function(plot,code){if(account)await loadSeason();return roomOrderLoaded(plot,code)};
notificationsPage=function(){const events=opsData?.notifications||[],groups=new Map();for(const n of events){const day=new Date(n.created_at).toLocaleDateString('ru-RU');if(!groups.has(day))groups.set(day,[]);groups.get(day).push(n)}return heading('🔔 Новости хозяйства','Важные изменения без постоянного мигания.')+`<button class="btn light" onclick="readFarmNews()">Отметить всё прочитанным</button>${[...groups].map(([day,rows])=>`<section class="panel"><h2>${day}</h2>${rows.map(n=>`<div class="event"><span>${n.read_at?'':'● '}${esc(n.message)}</span><small>${fmt(n.created_at)}</small></div>`).join('')}</section>`).join('')||'<p>Пока нет новых событий.</p>'}`};
async function readFarmNews(){try{await api('journey-read',{});await loadOperations()}catch(e){toast(e.message)}}
function productSetup(){formAsync('🛍️ Карточка конкретного товара',`<label>Товар<select name="id">${demoCatalog.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.category)}</option>`).join('')}</select></label><label>Комплектация, размеры, материалы<textarea name="description" minlength="20" required></textarea></label><label>HTTPS-ссылка на фото именно этого товара<input type="url" name="photo"></label><label>Сорт или модель<input name="variety"></label><label>Номер партии<input name="lot"></label><label>Срок годности<input type="date" name="expires"></label><p>До добавления собственных данных показывается подписанная иллюстрация категории.</p><button class="btn">Сохранить карточку</button>`,async f=>journeyAction('product',Object.fromEntries(f)))}
function observationForm(){formAsync('🌦️ Почему нужен уход',sp()+'<label>Состояние почвы<input name="soil" minlength="3" required></label><label>Погода и источник наблюдения<input name="weather" minlength="3" required></label><label>Стадия растения<input name="stage" minlength="3" required></label><label>Решение и причина<textarea name="decision" minlength="3" required></textarea></label><label>Материал, если нужен<input name="material"></label><label>Доза и площадь применения<input name="dose"></label><button class="btn">Зафиксировать наблюдение</button>',async f=>journeyAction('observation',{...Object.fromEntries(f),plot:Number(f.get('plot'))}))}
function staffBlockForm(){formAsync('👩‍🌾 Перерыв или отсутствие',`<label>Сотрудник<select name="worker">${(journeyData?.staff||[]).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label>С<input name="start" type="datetime-local" required></label><label>До<input name="end" type="datetime-local" required></label><label>Причина<input name="reason" minlength="3" required></label><button class="btn">Закрыть время для назначений</button>`,async f=>journeyAction('staff-block',{...Object.fromEntries(f),start:new Date(f.get('start')).toISOString(),end:new Date(f.get('end')).toISOString()}))}
scheduleOrder=async function(id){await loadJourney();formAsync('👩‍🌾 Предложить время работы',`<label>Исполнитель<select name="worker">${(journeyData?.staff||[]).map(w=>`<option value="${w.id}">${esc(w.name)}</option>`).join('')}</select></label><label>Начало интервала<input name="start" type="datetime-local" required></label><label>Завершение<input name="finish" type="datetime-local" required></label><p>Смена 09:00–19:00 МСК; между работами резервируем 10 минут. Учитываются отмеченные перерывы и отсутствие.</p><button class="btn">Предложить сроки</button>`,async f=>{await api('order-update',{id,to:'quoted',worker:f.get('worker'),start:new Date(f.get('start')).toISOString(),finish:new Date(f.get('finish')).toISOString()});await refreshCloud()})};
function rescheduleOrder(id){formAsync('🕒 Предложить перенос','<label>Новое начало<input name="start" type="datetime-local" required></label><label>Завершение<input name="end" type="datetime-local" required></label><label>Причина<textarea name="reason" minlength="10" required></textarea></label><p>Пользователь согласует новое время. Повторной оплаты уже оплаченной работы не будет.</p><button class="btn">Отправить предложение</button>',async f=>journeyAction('reschedule',{id,...Object.fromEntries(f),start:new Date(f.get('start')).toISOString(),end:new Date(f.get('end')).toISOString()}))}
const orderWithPayments=orderCard;orderCard=function(o){return orderWithPayments(o)+(account?.role==='admin'&&['quoted','awaiting_payment','queued'].includes(o.status)?`<button class="btn light" onclick="rescheduleOrder('${o.id}')">Предложить перенос</button>`:'')+(account&&['on_way','working','review','done'].includes(o.status)?`<button class="btn light" onclick="incidentForm('order','${o.id}')">Проблема с работой</button>`:'')};
farmViews.add(()=>{
 if(account?.role==='admin'&&location.hash==='#basket')document.getElementById('app').insertAdjacentHTML('beforeend','<section class="panel"><h2>🌦️ Управление заботой</h2><button class="btn light" onclick="observationForm()">Наблюдение перед уходом</button><button class="btn light" onclick="staffBlockForm()">Перерыв сотрудника</button><button class="btn light" onclick="productSetup()">Фото и состав товара</button></section>');
 const p=currentRoomPlot();if(p&&journeyData&&plotRoomTab==='grow'){const rows=(journeyData.observations||[]).filter(o=>o.plot_id===p.id);if(rows.length)document.querySelector('[role=tabpanel]')?.insertAdjacentHTML('beforeend',`<section class="panel"><h2>🌦️ Решения садовника</h2>${rows.slice(0,5).map(o=>`<p><b>${fmt(o.created_at)}</b><br>${esc(o.soil)} · ${esc(o.weather)} · ${esc(o.stage)}<br>${esc(o.decision)}${o.material?'<br>'+esc(o.material)+' · '+esc(o.dose):''}</p>`).join('')}</section>`)}
});
function quoteDelivery(id){formAsync('🚚 Стоимость и условия доставки','<label>Стоимость всей доставки, демо-₽<input name="price" type="number" min="0" step="0.01" required></label><label>Ожидаемое прибытие<input name="expected" type="datetime-local" required></label><label>Подтверждение адреса, интервала, упаковки и условий<textarea name="conditions" minlength="20" required></textarea></label><p>Создаётся предложение. Списание будет только после согласования владельцем корзины.</p><button class="btn">Предложить доставку</button>',async f=>{await journeyAction('delivery-quote',{id,price:Math.round(Number(f.get('price'))*100),expected:new Date(f.get('expected')).toISOString(),conditions:f.get('conditions')});await loadLife()})}
function payDelivery(id){const d=lifeData?.deliveries.find(x=>x.id===id),q=d?.delivery_quote;if(!q)return;formAsync('🚚 Корзина отправится к вам',`<p>${esc(q.address)}</p><p>${esc(q.conditions)}</p><p>Прибытие: ${fmt(q.expected)}</p><h3>${money(q.price)} демосредствами</h3><button class="btn">Согласовать и оплатить демобалансом</button>`,async()=>{await journeyAction('delivery-pay',{id,version:q.version});walletData=null;await loadLife()})}
const deliveryWithReceipt=changeDelivery;changeDelivery=async function(id,status){if(status==='confirmed')return quoteDelivery(id);return deliveryWithReceipt(id,status)};
farmViews.add(()=>{if(['#lifecycle','#delivery'].includes(location.hash)&&lifeData){const pending=lifeData.deliveries.filter(d=>d.status==='requested'&&d.delivery_quote);if(pending.length)document.getElementById('app').insertAdjacentHTML('afterbegin',`<section class="panel"><h2>🚚 Согласуйте доставку</h2>${pending.map(d=>`<article class="event"><b>${esc(d.recipient)}</b><p>${esc(d.delivery_quote.conditions)}</p><p>${money(d.delivery_quote.price)} · ${fmt(d.delivery_quote.expected)}</p>${d.user_id===account.id?`<button class="btn" onclick="payDelivery('${d.id}')">Согласовать стоимость</button>`:'Ожидаем решения владельца корзины'}</article>`).join('')}</section>`);}});
function repackBasket(id){formAsync('🧺 Изменить состав корзины','<p>Сначала отменим текущую корзину: урожай освободится, оплаченная демодоставка вернётся на баланс. Затем вы выберете новый состав и заново согласуете доставку.</p><button class="btn">Отменить и собрать новую корзину</button>',async()=>{await lifeAction('delivery-update',{id,status:'cancelled'});setTimeout(()=>basketForm(),0)})}
farmViews.add(()=>{if(['#lifecycle','#delivery'].includes(location.hash)&&lifeData){const baskets=lifeData.deliveries.filter(d=>d.user_id===account?.id&&['requested','confirmed'].includes(d.status));if(baskets.length)document.getElementById('app').insertAdjacentHTML('beforeend',`<section class="panel"><h2>Изменить состав до отправки</h2><p>Замены не выполняются без нового выбора владельца.</p>${baskets.map(d=>`<button class="btn light" onclick="repackBasket('${d.id}')">Пересобрать: ${esc(d.recipient)}</button>`).join('')}</section>`)}});
